from collections import Counter

def transform(grid):
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    active = [any(v != bg for v in row) for row in g]
    groups = []
    r = 0
    while r < h:
        if not active[r]:
            r += 1
            continue
        start = r
        while r < h and active[r]:
            r += 1
        groups.append((start, r))
    out = [row[:] for row in g]
    if len(groups) >= 2:
        (a0, a1), (b0, b1) = groups[0], groups[1]
        if a1 - a0 == b1 - b0:
            for dr in range(a1 - a0):
                for c in range(w):
                    if g[b0 + dr][c] != bg and g[a0 + dr][c] == bg:
                        out[a0 + dr][c] = 1
    return out
